// Configuración del sitio (se ejecuta al desplegar). La leen "Calcular índices",
// "Consultar viento" y "Leer viento". Para cambiar de sitio, cambia SITIO_ACTIVO.
const SITIOS = {
    merida:   { nombre: 'Mérida, Yucatán',   lat: 20.97, lon: -89.62, costa_km: 35 },
    progreso: { nombre: 'Progreso, Yucatán', lat: 21.28, lon: -89.66, costa_km: 0 }
};
const SITIO_ACTIVO = 'merida';

flow.set('mvp47sitio', Object.assign({
    mar_desde: 290, mar_hasta: 70,   // en ambos el mar está al norte (grados de donde viene el viento)
    brisa_kmh: 15,
    hr_sal_ext: 75                   // humedad exterior para el riesgo de sal del pronóstico
}, SITIOS[SITIO_ACTIVO]));
flow.set('mvp47modo', { sim: false });      // al desplegar o reiniciar, la página vuelve a datos reales
node.status({ fill: 'blue', shape: 'dot', text: SITIOS[SITIO_ACTIVO].nombre });
return null;

// Consultar viento: arma la URL de Open-Meteo (cada hora). El nodo http request usa msg.url.
// Datos de Open-Meteo, licencia CC BY 4.0 (dar crédito en el dashboard).
const S = flow.get('mvp47sitio');
if (!S) { node.status({ fill: 'red', shape: 'ring', text: 'falta configuración del sitio' }); return null; }
const VARS = 'temperature_2m,relative_humidity_2m,wind_speed_10m,wind_direction_10m';
msg.url = 'https://api.open-meteo.com/v1/forecast' +
    '?latitude=' + S.lat + '&longitude=' + S.lon +
    '&current=' + VARS + '&hourly=' + VARS +
    '&forecast_hours=24&wind_speed_unit=kmh&timezone=America%2FMexico_City';
msg.method = 'GET';
node.status({ fill: 'blue', shape: 'dot', text: 'consultando ' + S.nombre });
return msg;

// Leer viento: respuesta de Open-Meteo -> 2 salidas
//   1: { topic: 'viento', payload: { dir_deg, vel_kmh, temp, hum } }  para "Calcular índices"
//   2: resumen para el dashboard y Telegram: viento actual, desde el mar o no, y riesgo de sal en 24 h
const S = flow.get('mvp47sitio') || { nombre: '?', mar_desde: 290, mar_hasta: 70, brisa_kmh: 15, hr_sal_ext: 75, costa_km: null };
const HORAS_MIN_RIESGO = 2;          // ventana de al menos 2 h seguidas
const num = v => typeof v === 'number' && isFinite(v);
const enMar = d => S.mar_desde <= S.mar_hasta ? (d >= S.mar_desde && d <= S.mar_hasta)
                                               : (d >= S.mar_desde || d <= S.mar_hasta);
const brisa = (dir, vel) => enMar(dir) && vel >= S.brisa_kmh;
const PUNTOS = ['N', 'NE', 'E', 'SE', 'S', 'SO', 'O', 'NO'];
const punto = d => PUNTOS[Math.round(d / 45) % 8];

function falla(texto) {
    node.status({ fill: 'red', shape: 'ring', text: texto });
    return [null, { topic: 'pronostico', payload: { ok: false, sitio: S.nombre, texto: 'Sin datos de viento (' + texto + ')' } }];
}

if (msg.statusCode !== undefined && msg.statusCode !== 200) return falla('HTTP ' + msg.statusCode);
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return falla('respuesta no es JSON'); } }
if (!p || typeof p !== 'object' || !p.hourly || !Array.isArray(p.hourly.time)) return falla('respuesta incompleta');

const H = p.hourly;
const c = p.current || {};
const act = {
    dir_deg: num(c.wind_direction_10m) ? c.wind_direction_10m : H.wind_direction_10m && H.wind_direction_10m[0],
    vel_kmh: num(c.wind_speed_10m) ? c.wind_speed_10m : H.wind_speed_10m && H.wind_speed_10m[0],
    temp: num(c.temperature_2m) ? c.temperature_2m : H.temperature_2m && H.temperature_2m[0],
    hum: num(c.relative_humidity_2m) ? c.relative_humidity_2m : H.relative_humidity_2m && H.relative_humidity_2m[0]
};
if (!num(act.dir_deg) || !num(act.vel_kmh)) return falla('sin viento actual');

// Ventanas de riesgo: brisa marina y humedad exterior alta
const hoy = (typeof c.time === 'string' ? c.time : H.time[0]).slice(0, 10);
const ventanas = [];
let v = null;
H.time.forEach((t, i) => {
    const d = H.wind_direction_10m[i], s = H.wind_speed_10m[i], hr = H.relative_humidity_2m[i];
    const riesgo = num(d) && num(s) && num(hr) && brisa(d, s) && hr >= S.hr_sal_ext;
    if (riesgo) {
        if (!v) { v = { desde: t, hasta: t, horas: 0 }; ventanas.push(v); }
        v.hasta = t; v.horas++;
    } else v = null;
});
const reales = ventanas.filter(w => w.horas >= HORAS_MIN_RIESGO);
const dia = t => t.slice(0, 10) === hoy ? 'hoy' : 'mañana';
const hora = t => t.slice(11, 16);
const fin = t => { const h = (parseInt(t.slice(11, 13), 10) + 1) % 24; return (h < 10 ? '0' : '') + h + ':00'; };
const texto = reales.length
    ? 'Riesgo de sal: ' + reales.map(w => dia(w.desde) + ' ' + hora(w.desde) + '–' + fin(w.hasta)).join(', ') +
      '. Mantén puertas cerradas y el aire o deshumidificador encendido.'
    : 'Sin riesgo de sal en las próximas 24 h.';

const desdeMar = enMar(act.dir_deg);
node.status({ fill: reales.length ? 'yellow' : 'green', shape: 'dot',
              text: punto(act.dir_deg) + ' ' + act.vel_kmh + ' km/h' + (desdeMar ? ' (del mar)' : '') });
return [
    { topic: 'viento', payload: act },
    { topic: 'pronostico', payload: {
        ok: true, sitio: S.nombre, costa_km: S.costa_km,
        actual: Object.assign({}, act, { punto: punto(act.dir_deg), desde_mar: desdeMar, brisa: brisa(act.dir_deg, act.vel_kmh) }),
        riesgo: reales.length > 0, ventanas: reales, texto: texto,
        fuente: 'Open-Meteo (CC BY 4.0)'
    } }
];

// Simulador (modo simulación del dashboard). Entradas:
//   topic 'sim/control' -> { accion: 'iniciar' | 'detener' }   (botón de la página)
//   topic 'tick'        -> cada 1 s
// Salidas: 1 -> "Calcular índices" (mensajes con msg.sim = true)   2 -> "Evaluar umbrales" (pronóstico, estado de nodos y refrescar)
// No publica en MQTT: la simulación no se ve en la página 4.3 y usa contadores aparte de los reales.
// 9 fases de 20 s (3 min por ciclo). Con 180× cada fase cuenta como 1 h simulada.
const DUR = 20;
const ACEL = 180;                 // igual que ACELERACION_SIM de "Calcular índices"
const FASES = [
    { id: 'normal', nombre: 'Oficina normal', texto: '23 °C, 50 % y poco polvo: todo en verde' },
    { id: 'noche', nombre: 'Noche sin aire acondicionado', texto: 'sube poco a poco a 30 °C y 82 %, con viento del mar' },
    { id: 'rocio', nombre: 'Condensación', texto: '25 °C y 92 %: a menos de 2 °C del punto de rocío' },
    { id: 'subida', nombre: 'Subida rápida en todo el rack', texto: 'las posiciones A y B suben de 24 a 33 °C en 5 s: falla el aire acondicionado' },
    { id: 'subida_local', nombre: 'Subida rápida local', texto: 'solo la posición A sube a 31 °C: un equipo o el flujo de aire cerca de A' },
    { id: 'flama', nombre: 'Flama en el rack', texto: 'el sensor de flama de la posición A detecta fuego' },
    { id: 'desconexion', nombre: 'Nodo desconectado', texto: 'el nodo de ambiente amb-01 se desconecta y vuelve' },
    { id: 'polvo', nombre: 'Episodio de polvo', texto: 'PM10 de 300 µg/m³ (limpieza u obra cercana)' },
    { id: 'falla', nombre: 'Falla del sensor de partículas', texto: 'tramas perdidas y valores imposibles (se recupera al empezar el siguiente ciclo)' }
].map(f => Object.assign(f, { dur: DUR }));
const CICLO = FASES.reduce((s, f) => s + f.dur, 0);
const ahora = Date.now();
const M = flow.get('mvp47modo') || { sim: false };
const S = flow.get('mvp47sitio') || { nombre: 'Sitio', costa_km: null };

const ruido = a => (Math.random() - 0.5) * 2 * a;
const r2 = v => Math.round(v * 100) / 100;
function rocio(t, h) { const a = 17.62, b = 243.12, g = Math.log(h / 100) + a * t / (b + t); return r2(b * g / (a - g)); }
function faseEn(seg) {
    let s = seg % CICLO;
    for (let i = 0; i < FASES.length; i++) { if (s < FASES[i].dur) return { i: i, f: FASES[i], tf: s }; s -= FASES[i].dur; }
    return { i: 0, f: FASES[0], tf: 0 };
}
function rackEn(id, tf) {
    const x = Math.min(1, tf / DUR);
    switch (id) {
        case 'noche': return [23 + 7 * x, 50 + 32 * x];          // gradual: no cuenta como subida rápida
        case 'rocio': return [25, 92];
        case 'subida': return [24 + 9 * Math.min(1, tf / 5), 55];  // +9 °C en 5 s (15 min simulados)
        case 'subida_local': return [24 + 7 * Math.min(1, tf / 5), 50];   // solo la posición A (ver mensajeRack)
        case 'normal': return [23, 50];
        default: return [24, 50];
    }
}
function estado(id, st) {
    return { topic: 'site/estado/' + id, sim: true, payload: { schema: 1, type: 'status', node_id: id, status: st } };
}
function mensajeRack(fz) {
    const [t, h] = rackEn(fz.f.id, fz.tf);
    M.seq = (M.seq || 0) + 1;
    M.prev = M.prev || {};
    const pos = ['A', 'B'].map((id, k) => {
        const tp = fz.f.id === 'subida_local' && id === 'B' ? 24 : t;      // en la subida local B no se mueve
        const temp = r2(tp - 0.4 * k + ruido(0.08)), hum = r2(Math.min(99, h - 1 * k + ruido(0.3)));
        const ant = M.prev[id];
        const tasa = ant ? r2((temp - ant.t) / ((ahora - ant.ts) * ACEL / 60000)) : 0;   // °C por minuto SIMULADO
        M.prev[id] = { t: temp, ts: ahora };
        const p = { id: id, temp: temp, hum: hum, dew_point: rocio(temp, hum), rate_c_min: tasa };
        if (id === 'A') p.flame = fz.f.id === 'flama';
        return p;
    });
    return { topic: 'site/datos', sim: true, payload: { schema: 1, type: 'rack', node_id: 'rack-01', seq: M.seq,
             uptime_s: Math.round((ahora - M.inicio) / 1000), positions: pos } };
}
function mensajeAmbiente(fz) {
    const [t, h] = rackEn(fz.f.id, fz.tf);
    M.seqAmb = (M.seqAmb || 0) + 1;
    const temp = r2(t - 0.5 + ruido(0.1)), hum = r2(Math.min(99, h + ruido(0.5)));
    const m = { schema: 1, type: 'ambiente', node_id: 'amb-01', seq: M.seqAmb, uptime_s: Math.round((ahora - M.inicio) / 1000),
                temp: temp, hum: hum, dew_point: rocio(temp, hum), rate_c_min: 0 };
    if (fz.f.id === 'polvo') Object.assign(m, { pm1_0: 90, pm2_5: 150, pm10: Math.round(300 + ruido(15)) });
    else if (fz.f.id === 'falla') {
        if (M.seqAmb % 2) Object.assign(m, { pm1_0: null, pm2_5: null, pm10: null, err: ['pms_sin_trama'] });
        else Object.assign(m, { pm1_0: 30, pm2_5: 20, pm10: 25 });                  // imposible: PM1.0 > PM2.5
    } else Object.assign(m, { pm1_0: 9, pm2_5: 14, pm10: Math.round(21 + ruido(2)) });
    return { topic: 'site/datos', sim: true, payload: m };
}
function pronosticoSimulado() {
    const h = new Date(ahora + 3600000);
    const hh = n => String(n % 24).padStart(2, '0') + ':00';
    const texto = 'Riesgo de sal (simulado): hoy ' + hh(h.getHours()) + '–' + hh(h.getHours() + 5) +
                  '. Mantén puertas cerradas y el aire o deshumidificador encendido.';
    return { topic: 'pronostico', sim: true, payload: {
        ok: true, sitio: S.nombre, costa_km: S.costa_km, riesgo: true, texto: texto,
        ventanas: [{ desde: 'sim-' + ahora, hasta: 'sim', horas: 5 }],
        actual: { dir_deg: 10, vel_kmh: 25, temp: 29, hum: 85, punto: 'N', desde_mar: true, brisa: true },
        fuente: 'Simulación (no son datos reales)' } };
}
const infoFase = (fz, ciclo) => ({ n: fz.i + 1, id: fz.f.id, total: FASES.length, nombre: fz.f.nombre, texto: fz.f.texto,
                                   quedan_s: Math.ceil(fz.f.dur - fz.tf), ciclo: ciclo });

if (msg.topic === 'sim/control') {
    const accion = msg.payload && msg.payload.accion;
    if (accion === 'iniciar') {
        flow.set('mvp47sim', undefined);                 // contadores de simulación desde cero
        flow.set('mvp47alertas_sim', undefined);
        const fz = faseEn(0);
        flow.set('mvp47modo', { sim: true, inicio: ahora, seq: 0, seqAmb: 0, ultRack: 0, ultAmb: 0, fase: infoFase(fz, 1) });
        node.status({ fill: 'blue', shape: 'dot', text: 'simulando: ' + fz.f.nombre });
        return [{ topic: 'viento', sim: true, payload: { dir_deg: 10, vel_kmh: 25 } },
                [estado('rack-01', 'online'), estado('amb-01', 'online'), pronosticoSimulado(), { topic: 'refrescar' }]];
    }
    if (accion === 'detener') {
        flow.set('mvp47modo', { sim: false });
        node.status({});
        return [null, { topic: 'refrescar' }];
    }
    return null;
}
if (msg.topic !== 'tick' || !M.sim) return null;

const seg = (ahora - M.inicio) / 1000;
const fz = faseEn(seg);
const ciclo = Math.floor(seg / CICLO) + 1;
const antes = M.fase ? M.fase.id : null;
const salida = [], aEval = [];
if (M.fase && ciclo !== M.fase.ciclo) salida.push({ topic: 'viento', sim: true, payload: { dir_deg: 10, vel_kmh: 25 } });   // renueva el viento cada ciclo
if (fz.f.id === 'desconexion' && antes !== 'desconexion') aEval.push(estado('amb-01', 'offline'));
if (fz.f.id !== 'desconexion' && antes === 'desconexion') aEval.push(estado('amb-01', 'online'));
if (ahora - (M.ultRack || 0) >= 2000) { salida.push(mensajeRack(fz)); M.ultRack = ahora; }
// el ambiente manda cada 1 s en la simulación (cada 5 s en el nodo real) y calla mientras está desconectado
if (fz.f.id !== 'desconexion' && ahora - (M.ultAmb || 0) >= 1000) { salida.push(mensajeAmbiente(fz)); M.ultAmb = ahora; }
M.fase = infoFase(fz, ciclo);
flow.set('mvp47modo', M);
node.status({ fill: 'blue', shape: 'dot', text: 'fase ' + M.fase.n + '/' + FASES.length + ': ' + fz.f.nombre });
return [salida.length ? salida : null, aEval.length ? aEval : null];

// Calcular índices (tarea 4.7). Entrada:
//   topic 'site/datos'    -> mensaje del contrato JSON v1 (rack o ambiente)
//   topic 'viento'        -> { dir_deg, vel_kmh } desde la API (cada hora)
//   topic 'mantenimiento' -> { indice: 'envejecimiento'|'corrosion'|'polvo'|'termico'|'condensacion'|'pms' }
// Si msg.sim === true (o el modo simulación está activo para 'mantenimiento'), usa contadores aparte:
// la simulación nunca toca los acumulados reales.
// Salida: msg.payload = { indices, actual, bitacora, aceleracion, sim }
const CFG = {
    ACELERACION: 1,                 // modo demo: 60 = una hora por minuto (declararlo al jurado).
                                    // Solo acelera lo acumulado; subidas y PM fijo usan tiempo real
                                    // (en la simulación la subida también usa tiempo simulado).
    ACELERACION_SIM: 180,           // la simulación del dashboard usa 180×: cada fase de 20 s cuenta como 1 h
    HUECO_MS: { rack: 10000, ambiente: 20000 },   // más tiempo sin datos = no se acumula
    PECK: { Ea: 0.79, n: 2.7, k: 8.617e-5, T_REF: 25, HR_REF: 50 },
    HR_ALTA: 60, HR_SAL: 75,        // ASHRAE (delicuescencia) y sal marina
    T_RECOMENDADA: 27, T_PERMITIDA: 32,           // ASHRAE recomendado y A1 permitido
    SUBIDA_C: 5, SUBIDA_MS: 15 * 60000,           // ASHRAE: máx. 5 °C en 15 min
    MARGEN_ROCIO: 3,                // °C entre temperatura y punto de rocío
    PM10_ALTO: 150,                 // µg/m³: límite diario de la EPA, usado como referencia de episodio de polvo
    MAR_DESDE: 290, MAR_HASTA: 70,  // sector del mar (grados de donde viene el viento)
    BRISA_KMH: 15,
    VIENTO_VIGENCIA_MS: 2 * 3600000,
    PM_FIJO_MS: 3600000,            // PM idéntico por 1 h = sospechoso
    VENTANA_PMS: 120,               // salud del PMS5003: últimas 120 tramas (10 min a 5 s)
    VENTANA_PMS_DEMO: 12            // con tiempo acelerado (simulación o demo): últimas 12 tramas (1 min)
};
const SITIO = flow.get('mvp47sitio');     // lo escribe "Configuración del sitio"
if (SITIO) { CFG.MAR_DESDE = SITIO.mar_desde; CFG.MAR_HASTA = SITIO.mar_hasta; CFG.BRISA_KMH = SITIO.brisa_kmh; }
const MODO = flow.get('mvp47modo') || { sim: false };
const SIM = msg.sim === true || (msg.topic === 'mantenimiento' && MODO.sim === true);
const ACEL = SIM ? CFG.ACELERACION_SIM : CFG.ACELERACION;
const VENTANA = ACEL > 1 ? CFG.VENTANA_PMS_DEMO : CFG.VENTANA_PMS;
const K = SIM ? 'mvp47sim' : 'mvp47';
const SUBIDA_MS = SIM ? CFG.SUBIDA_MS / ACEL : CFG.SUBIDA_MS;   // 15 min (simulados en la simulación)
const PASO_HIST_MS = SIM ? 30000 / ACEL : 30000;
const ahora = Date.now();

function nuevo() {
    const z = () => ({ desde: ahora });
    return {
        indices: {
            envejecimiento: Object.assign(z(), { horas_eq: 0, horas: 0 }),
            corrosion: Object.assign(z(), { h_hr60: 0, h_hr75: 0, h_brisa: 0 }),
            polvo: Object.assign(z(), { ugh: 0 }),
            termico: Object.assign(z(), { min27: 0, min32: 0, subidas: 0, ultima: null }),
            condensacion: Object.assign(z(), { min: 0 }),
            pms: Object.assign(z(), { horas: 0, ugh: 0, tramas: 0, perdidas: 0, imposibles: 0, min_fijo: 0 })
        },
        ultimo: {}, historial: {}, armado: {}, episodio: {}, viento: null, pmPrevio: null, ventanaPms: [],
        actual: {}, bitacora: []
    };
}
const S = flow.get(K) || nuevo();
S.ventanaPms = S.ventanaPms || [];
S.episodio = S.episodio || {};

const P_ = CFG.PECK;
const fTemp = t => Math.exp(P_.Ea / P_.k * (1 / (P_.T_REF + 273.15) - 1 / (t + 273.15)));   // Arrhenius
const fHum = hr => Math.pow(hr / P_.HR_REF, P_.n);                                          // humedad (Peck)
const peck = (t, hr) => hr > 0 ? fHum(hr) * fTemp(t) : null;
const num = v => typeof v === 'number' && isFinite(v);
function enMar(d) {
    return CFG.MAR_DESDE <= CFG.MAR_HASTA ? (d >= CFG.MAR_DESDE && d <= CFG.MAR_HASTA)
                                          : (d >= CFG.MAR_DESDE || d <= CFG.MAR_HASTA);
}
function brisaActiva() {
    const v = S.viento;
    if (!v || ahora - v.ts > CFG.VIENTO_VIGENCIA_MS) return null;      // sin datos de viento
    return enMar(v.dir_deg) && v.vel_kmh >= CFG.BRISA_KMH;
}
// Δt en horas (acelerado), 0 si hubo hueco o es el primer mensaje
function deltaH(id, tipo) {
    const prev = S.ultimo[id];
    S.ultimo[id] = ahora;
    if (prev === undefined) return 0;
    const dt = ahora - prev;
    if (dt <= 0 || dt > CFG.HUECO_MS[tipo]) return 0;
    return dt * ACEL / 3600000;
}
// cuánto subió una posición en la ventana de 15 min (sin modificar el historial)
function aumento(clave, t) {
    const h = S.historial[clave] || [];
    return t - Math.min.apply(null, h.map(x => x[1]).concat([t]));
}
// subidas > 5 °C en 15 min por posición; se rearma cuando vuelve a menos de la mitad
function revisarSubida(clave, t) {
    const h = (S.historial[clave] = S.historial[clave] || []);
    const ultimo = h[h.length - 1];
    if (!ultimo || ahora - ultimo[0] >= PASO_HIST_MS) h.push([ahora, t]);
    while (h.length && ahora - h[0][0] > SUBIDA_MS) h.shift();
    const min = Math.min.apply(null, h.map(x => x[1]).concat([t]));
    if (t - min > CFG.SUBIDA_C) {
        if (S.armado[clave] !== false) { S.armado[clave] = false; return true; }
    } else if (t - min < CFG.SUBIDA_C / 2) {
        S.armado[clave] = true;
    }
    return false;
}
function valido(m) {
    return m && typeof m === 'object' && m.schema === 1 && typeof m.node_id === 'string' &&
        (m.type === 'rack' ? Array.isArray(m.positions) : m.type === 'ambiente');
}
const A = S.actual;
A.subida_ahora = false;
A.subida_evento = null;          // 'nueva' | 'ahora_general' (solo en el mensaje donde ocurre)

if (msg.topic === 'viento') {
    const p = msg.payload || {};
    if (num(p.dir_deg) && num(p.vel_kmh)) S.viento = { dir_deg: p.dir_deg, vel_kmh: p.vel_kmh, ts: ahora };
} else if (msg.topic === 'mantenimiento') {
    const nombre = msg.payload && msg.payload.indice;
    if (!S.indices[nombre]) return null;
    S.indices[nombre] = nuevo().indices[nombre];
    if (nombre === 'pms') S.ventanaPms = [];
    S.bitacora.unshift({ indice: nombre, ts: ahora });
    S.bitacora = S.bitacora.slice(0, 20);
} else if (msg.topic === 'site/datos') {
    let m = msg.payload;
    if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { return null; } }
    if (!valido(m)) return null;
    const I = S.indices;
    const dh = deltaH(m.node_id, m.type);
    const dmin = dh * 60;

    if (m.type === 'rack') {
        A.flama = m.positions.some(p => p.flame === true);
        const pos = m.positions.filter(p => num(p.temp) && num(p.hum));
        if (pos.length) {
            let peor = pos[0];
            pos.forEach(p => { if (peck(p.temp, p.hum) > peck(peor.temp, peor.hum)) peor = p; });
            const fa = peck(peor.temp, peor.hum) || 0;
